import os
import hashlib
import json
from pathlib import PurePosixPath
from typing import Optional, Dict, Any

# Container orchestration tool - volume mount configuration manager
# Supports feature flags for experimental volume drivers

FEATURE_FLAGS = {
    "enable_nfs_volumes": True,
    "enable_overlay_mounts": True,
    "enable_symlink_resolution": True,
    "enable_path_normalization": True,
    "strict_sandbox_mode": True,
}

CONTAINER_ROOT = "/var/lib/containers"
ALLOWED_VOLUME_BASES = ["/data", "/config", "/logs", "/tmp"]


class VolumePathResolver:
    """Resolves and validates volume mount paths for containers."""

    def __init__(self, container_id: str, feature_flags: Dict[str, bool]):
        self.container_id = self._sanitize_id(container_id)
        self.flags = feature_flags
        self.sandbox_root = os.path.join(CONTAINER_ROOT, self.container_id)

    @staticmethod
    def _sanitize_id(container_id: str) -> str:
        """Ensure container ID is a valid hex string."""
        cleaned = container_id.strip().lower()
        if not all(c in '0123456789abcdef' for c in cleaned):
            raise ValueError(f"Invalid container ID: {container_id}")
        if len(cleaned) < 12 or len(cleaned) > 64:
            raise ValueError(f"Container ID length invalid: {len(cleaned)}")
        return cleaned

    def _normalize_path(self, path: str) -> str:
        """Normalize path components, handling feature flags."""
        if self.flags.get("enable_path_normalization"):
            # Use PurePosixPath for platform-independent normalization
            normalized = str(PurePosixPath(path))
            return normalized
        return path

    def _check_sandbox_boundary(self, resolved_path: str) -> bool:
        """Verify path stays within sandbox boundaries."""
        # Always enforce sandbox - ignore feature flag for security
        # Canonicalize both paths for comparison
        canonical_sandbox = os.path.realpath(self.sandbox_root)
        canonical_target = os.path.realpath(resolved_path)
        return canonical_target.startswith(canonical_sandbox + os.sep) or \
               canonical_target == canonical_sandbox

    def _resolve_volume_path(self, volume_spec: str) -> str:
        """Core path resolution logic for volume specifications.

        Volume spec format: <base>:<relative_path>
        Example: /data:models/v2
        """
        parts = volume_spec.split(":", 1)
        if len(parts) != 2:
            raise ValueError(f"Invalid volume spec format: {volume_spec}")

        base, relative = parts[0], parts[1]

        # Validate base is in allowed list
        if base not in ALLOWED_VOLUME_BASES:
            raise ValueError(f"Volume base '{base}' not in allowed list")

        # Normalize the relative path
        relative = self._normalize_path(relative)

        # Security check: reject obvious traversal attempts
        if ".." in relative.split("/"):
            raise ValueError(f"Path traversal detected in: {relative}")

        # Construct the full path within the container sandbox
        full_path = os.path.join(self.sandbox_root, base.lstrip("/"), relative)
        return full_path

    def resolve_mount(self, volume_spec: str, driver: str = "local") -> Dict[str, Any]:
        """Resolve a volume mount specification to a concrete path."""
        if driver == "nfs" and not self.flags.get("enable_nfs_volumes"):
            raise PermissionError("NFS volumes are disabled")
        if driver == "overlay" and not self.flags.get("enable_overlay_mounts"):
            raise PermissionError("Overlay mounts are disabled")

        resolved_path = self._resolve_volume_path(volume_spec)

        # Apply symlink resolution if enabled
        if self.flags.get("enable_symlink_resolution"):
            resolved_path = self._follow_symlinks(resolved_path)

        # Final sandbox check - always enforced regardless of flags
        if not self._check_sandbox_boundary(resolved_path):
            raise PermissionError(
                f"Path '{resolved_path}' escapes sandbox '{self.sandbox_root}'"
            )

        return {
            "host_path": resolved_path,
            "container_path": volume_spec.split(":")[0],
            "driver": driver,
            "container_id": self.container_id,
            "sandbox_verified": True
        }

    def _follow_symlinks(self, path: str) -> str:
        """Resolve symlinks within the path, with depth limit."""
        max_depth = 10
        current = path
        for _ in range(max_depth):
            if os.path.islink(current):
                link_target = os.readlink(current)
                if not os.path.isabs(link_target):
                    current = os.path.join(os.path.dirname(current), link_target)
                else:
                    current = link_target
            else:
                break
        return current


class ContainerVolumeManager:
    """Manages volume mounts for container fleet."""

    def __init__(self, flags: Optional[Dict[str, bool]] = None):
        self.flags = flags or FEATURE_FLAGS.copy()
        self._mount_cache: Dict[str, Dict[str, Any]] = {}

    def create_volume_mount(self, container_id: str, volume_spec: str,
                           driver: str = "local") -> Dict[str, Any]:
        """Create and register a volume mount for a container."""
        resolver = VolumePathResolver(container_id, self.flags)
        mount_info = resolver.resolve_mount(volume_spec, driver)

        cache_key = hashlib.sha256(
            f"{container_id}:{volume_spec}".encode()
        ).hexdigest()[:16]
        self._mount_cache[cache_key] = mount_info

        return mount_info

    def batch_mount(self, container_id: str, specs: list) -> list:
        """Process multiple volume mount specifications."""
        results = []
        for spec in specs:
            if isinstance(spec, dict):
                result = self.create_volume_mount(
                    container_id, spec["path"], spec.get("driver", "local")
                )
            else:
                result = self.create_volume_mount(container_id, spec)
            results.append(result)
        return results


def handle_mount_request(request_body: str) -> Dict[str, Any]:
    """HTTP handler for volume mount API requests."""
    try:
        request = json.loads(request_body)
    except json.JSONDecodeError:
        return {"error": "Invalid JSON", "status": 400}

    container_id = request.get("container_id", "")
    volume_spec = request.get("volume_spec", "")
    driver = request.get("driver", "local")
    # Feature flags are NOT overridable from requests in production
    # Only use server-configured flags

    manager = ContainerVolumeManager(FEATURE_FLAGS.copy())
    try:
        result = manager.create_volume_mount(container_id, volume_spec, driver)
        return {"status": 200, "mount": result}
    except (ValueError, PermissionError) as e:
        return {"error": str(e), "status": 403}
